gdO(){return"\u10de\u10da\u10d0\u10e2\u10e4\u10dd\u10e0\u10db\u10d8\u10e1 \u10ec\u10d4\u10e1\u10d4\u10d1\u10d8"},
gdR(){return"\u10db\u10dd\u10db\u10e1\u10d0\u10ee\u10e3\u10e0\u10d4\u10d1\u10d8\u10e1 \u10de\u10d8\u10e0\u10dd\u10d1\u10d4\u10d1\u10d8"},
gcE(){return"\u10ee\u10e8\u10d8\u10e0\u10d0\u10d3 \u10d3\u10d0\u10e1\u10db\u10e3\u10da\u10d8 \u10d9\u10d8\u10d7\u10ee\u10d5\u10d4\u10d1\u10d8"},
gdI(){return"\u10d8\u10e3\u10e0\u10d8\u10d3\u10d8\u10e3\u10da\u10d8 \u10d8\u10dc\u10e4\u10dd\u10e0\u10db\u10d0\u10ea\u10d8\u10d0"},
