gbm(a){return"\u0410\u043b\u0434\u0430\u0430 \u0433\u0430\u0440\u043b\u0430\u0430. \u0414\u0430\u0445\u0438\u043d \u043e\u0440\u043e\u043b\u0434\u043e\u043d\u043e \u0443\u0443"},
geb(){return"\u0418\u043b\u0433\u044d\u044d\u0445\u0438\u0439\u043d \u04e9\u043c\u043d\u04e9 \u0431\u04af\u0445 \u0445\u044d\u0441\u0433\u0438\u0439\u0433 \u0431\u04e9\u0433\u043b\u04e9\u043d\u04e9 \u04af\u04af"},
ge5(){return"\u0422\u0430 Edhomy-\u0438\u0439\u043d \u0430\u0436\u0438\u043b\u0442\u0430\u043d \u0431\u043e\u043b \u043d\u044d\u0432\u0442\u044d\u0440\u0447 \u043e\u0440\u043d\u043e \u0443\u0443"},
geQ(){return"\u0425\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447 \u043d\u044d\u0440 \u0431\u0430 \u043d\u0443\u0443\u0446 \u04af\u0433"},
geT(){return"\u0425\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447 \u043d\u044d\u0440\u044d\u044d \u043e\u0440\u0443\u0443\u043b\u043d\u0430 \u0443\u0443"},
gem(){return"\u041d\u0443\u0443\u0446 \u04af\u0433\u044d\u044d \u043e\u0440\u0443\u0443\u043b\u043d\u0430 \u0443\u0443"},
gds(a){return"\u0411\u0430\u0442\u0430\u043b\u0433\u0430\u0430\u0436\u0443\u0443\u043b\u0430\u0445"},
geN(){return"\u041d\u0443\u0443\u0446 \u04af\u0433 \u044d\u0441\u0432\u044d\u043b \u0445\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447 \u043d\u044d\u0440 \u0431\u0443\u0440\u0443\u0443 \u0431\u0430\u0439\u043d\u0430. \u0425\u044f\u043d\u0430\u043b\u0442\u044b\u043d \u0434\u0430\u0440\u0433\u0430\u0442\u0430\u0439 \u0445\u043e\u043b\u0431\u043e\u0433\u0434\u043e\u043d\u043e \u0443\u0443"},
gez(){return"\u0425\u044d\u0440\u044d\u0433\u043b\u044d\u0433\u0447 \u043d\u044d\u0440 \u0431\u0430 \u043d\u0443\u0443\u0446 \u04af\u0433\u044d\u044d \u0437\u04e9\u0432 \u043e\u0440\u0443\u0443\u043b\u043d\u0430 \u0443\u0443"},
gcG(){return"\u0413\u0430\u0440\u0430\u0445"},
ge4(){return"\u041f\u0440\u043e\u0433\u0440\u0430\u043c \u0445\u0430\u043d\u0433\u0430\u043c\u0436"},
gcW(){return"\u042d\u043d\u044d \u0445\u0430\u0439\u043b\u0442\u0430\u0434 \u043c\u044d\u0434\u044d\u044d\u043b\u044d\u043b \u043e\u043b\u0434\u0441\u043e\u043d\u0433\u04af\u0439"},
gdN(){return"\u0413\u0430\u0440\u0447\u0438\u0433\u0438\u0439\u043d \u0434\u0430\u0433\u0443\u0443 \u044d\u0440\u044d\u043c\u0431\u044d\u043b\u044d\u0445"},
